      if (!catId) continue;
      coachInitializedRef.current.add(t.id);
      const allSvcs = flattenAllServices();
      const svc = allSvcs.find((s: any) => s.sku === t.productName || s.id === t.productName);
      const svcName: string = svc?.name || t.productName;
