                                // '__none__' = user explicitly clicked back to grid; ignore derivedCatId
                                const activeCatId = openCategoryId === '__none__' ? null : (openCategoryId ?? derivedCatId);
                                const activeCat = SERVICE_CATEGORIES.find((c) => c.id === activeCatId);
